class TestQueueCapacity:
    """Validate queue capacity limits and backpressure."""

    @pytest.mark.asyncio
    async def test_queue_overflow_rejected(self):
        """Messages beyond queue capacity should be rejected."""
        config = NetworkConfig(
            latency_ms=(0.0, 0.0),
            packet_loss_rate=0.0,
            reorder_rate=0.0,
            max_queue_size=5,
            seed=0,
        )
        net = NetworkMock(config)

        # Fill the queue
        for i in range(5):
            msg = Message(sender="a", recipient="b", msg_type=MessageType.DATA)
            await net.send(msg)

        # This should raise or return False
        overflow_msg = Message(sender="a", recipient="b", msg_type=MessageType.DATA)
        with pytest.raises((QueueFullError, RuntimeError, ValueError)):
            await net.send(overflow_msg)

    @pytest.mark.asyncio
    async def test_queue_drains_after_receive(self, network):
        """Queue should accept new messages after draining."""
        config = NetworkConfig(
            latency_ms=(0.0, 0.0),
            packet_loss_rate=0.0,
            reorder_rate=0.0,
            max_queue_size=2,
            seed=0,
        )
        net = NetworkMock(config)

        # Fill queue
        for i in range(2):
            msg = Message(sender="a", recipient="b", msg_type=MessageType.DATA)
            await net.send(msg)

        # Drain one message
        delivered = await net.receive("b")
        assert delivered is not None

        # Should be able to send again
        msg = Message(sender="a", recipient="b", msg_type=MessageType.DATA)
        await net.send(msg)

    @pytest.mark.asyncio
    async def test_queue_size_tracking(self, network):
        """Queue size should be tracked accurately."""
        assert network.queue_size() == 0

        msg1 = Message(sender="a", recipient="b", msg_type=MessageType.DATA)
        msg2 = Message(sender="a", recipient="b", msg_type=MessageType.DATA)
        await network.send(msg1)
        await network.send(msg2)

        assert network.queue_size() == 2

        await network.receive("b")
        assert network.queue_size() == 1


