class TestPerformance:
    """Validate performance under load."""

    @pytest.mark.asyncio
    async def test_high_throughput(self, network):
        """Network should handle high message volume."""
        message_count = 500
        start = time.monotonic()

        for i in range(message_count):
            msg = Message(
                sender="a",
                recipient="b",
                msg_type=MessageType.DATA,
                payload={"seq": i},
            )
            await network.send(msg)

        received = 0
        for _ in range(message_count):
            delivered = await network.receive("b")
            if delivered is not None:
                received += 1

        elapsed = time.monotonic() - start
        assert received == message_count
        assert elapsed < 5.0  # Should complete in under 5 seconds

    @pytest.mark.asyncio
    async def test_concurrent_senders(self, network):
        """Multiple concurrent senders should not corrupt state."""
        async def send_messages(sender_id: str, count: int):
            for i in range(count):
                msg = Message(
                    sender=sender_id,
                    recipient="collector",
                    msg_type=MessageType.DATA,
                    payload={"sender": sender_id, "seq": i},
                )
                await network.send(msg)

        senders = [send_messages(f"node-{i}", 50) for i in range(5)]
        await asyncio.gather(*senders)

        received = 0
        for _ in range(250):
            delivered = await network.receive("collector")
            if delivered is not None:
                received += 1

        assert received == 250


