class TestIntegration:
    """End-to-end integration scenarios."""

    @pytest.mark.asyncio
    async def test_full_message_lifecycle(self, network):
        """Complete message lifecycle: send, route, receive, acknowledge."""
        # Setup
        sender = "producer"
        recipient = "consumer"
        network.register_node(sender)
        network.register_node(recipient)

        # Send
        msg = Message(
            sender=sender,
            recipient=recipient,
            msg_type=MessageType.DATA,
            payload={"order_id": "12345", "amount": 99.99},
        )
        await network.send(msg)

        # Receive
        delivered = await network.receive(recipient)
        assert delivered is not None
        assert delivered.payload["order_id"] == "12345"
        assert delivered.payload["amount"] == 99.99

        # Acknowledge
        ack = Message(
            sender=recipient,
            recipient=sender,
            msg_type=MessageType.ACK,
            payload={"original_id": delivered.message_id},
        )
        await network.send(ack)

        ack_received = await network.receive(sender)
        assert ack_received is not None
        assert ack_received.msg_type == MessageType.ACK

    @pytest.mark.asyncio
    async def test_multi_hop_routing(self, network):
        """Messages should route through intermediate nodes."""
        # Setup chain: A -> B -> C
        network.register_node("node-a")
        network.register_node("node-b")
        network.register_node("node-c")

        # Send from A to C (through B)
        msg = Message(
            sender="node-a",
            recipient="node-c",
            msg_type=MessageType.DATA,
            payload={"hop": "test"},
        )
        await network.send(msg)

        # B should not receive it (direct routing)
        b_received = await network.receive("node-b")
        assert b_received is None

        # C should receive it
        c_received = await network.receive("node-c")
        assert c_received is not None
        assert c_received.payload["hop"] == "test"


