class TestProperties:
    """Property-based validation of network invariants."""

    @pytest.mark.asyncio
    @pytest.mark.parametrize("seed", range(5))
    async def test_message_count_conservation(self, seed):
        """Total messages sent should equal received + dropped."""
        config = NetworkConfig(
            latency_ms=(0.0, 10.0),
            packet_loss_rate=0.1,
            reorder_rate=0.1,
            max_queue_size=100,
            seed=seed,
        )
        net = NetworkMock(config)

        sent_count = 50
        received_count = 0

        for i in range(sent_count):
            msg = Message(
                sender="a",
                recipient="b",
                msg_type=MessageType.DATA,
                payload={"seq": i},
            )
            await net.send(msg)

        for _ in range(sent_count):
            delivered = await net.receive("b")
            if delivered is not None:
                received_count += 1

        # Conservation: received <= sent (some may be dropped)
        assert received_count <= sent_count
        assert received_count >= 0

    @pytest.mark.asyncio
    async def test_message_id_uniqueness_across_network(self, network):
        """No two delivered messages should share an ID."""
        seen_ids = set()
        for i in range(20):
            msg = Message(
                sender="a",
                recipient="b",
                msg_type=MessageType.DATA,
                payload={"seq": i},
            )
            await network.send(msg)

        for _ in range(20):
            delivered = await network.receive("b")
            if delivered is not None:
                assert delivered.message_id not in seen_ids
                seen_ids.add(delivered.message_id)

